const icon = (name,size=16) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.dot}</svg>`;
const state = {boot:null, filters:{scope:'all',collection:'',q:'',model:'',condition:'',signal:'',topic:'',tag:'',sort:'recent'},view:'library',offset:0,result:null,run:null,branch:null,compare:[],compareLabels:{},notes:[],noteQuery:'',selection:null,runQuery:'',request:0};
const names = {'stage-1':'Original self-play','stage-2':'Base & instruct models','stage-3':'Thinking & modified models',lab:'Laboratory campaigns'};
let searchTimer,toastTimer,routeVersion=0;

async function api(path, data){
 const response=await fetch(path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Explorer-Token':state.boot.token},body:JSON.stringify(data)});
 const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');return result;
}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function highlight(text,q){if(!q)return esc(text);const expression=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');let end=0,result='';for(const m of text.matchAll(expression)){result+=esc(text.slice(end,m.index))+'<mark>'+esc(m[0])+'</mark>';end=m.index+m[0].length;}return result+esc(text.slice(end));}
function stamp(value){if(!value)return 'Date not recorded';return value.slice(0,10).split('-').reverse().join(' · ');}
function go(values){if(values.run&&state.view==='workbench'){values.fromWorkbench=state.benchCohort;values.picks=(state.benchPicks||[]).join(',');}if((values.run||values.compare)&&state.view==='finder'){values.fromFinder=JSON.stringify(state.finderFilters||{});values.finderOffset=state.finderResult?.offset||0;}if(values.run&&state.activeStudy&&!values.fromStudy)values.fromStudy=state.activeStudy;if(values.run&&state.returnFinding&&!values.fromFinding)values.fromFinding=state.returnFinding;const hash=new URLSearchParams(values).toString();if(location.hash.slice(1)===hash)route();else location.hash=hash;}
function listRoute(view=state.view){const values=view==='library'?{}:{view};for(const [key,value] of Object.entries(state.filters)){if(value&&!(key==='scope'&&value==='all')&&!(key==='sort'&&value==='recent'))values[key]=value;}if(state.offset)values.offset=state.offset;return values;}
function library(view=state.view){go(listRoute(view));}
function collectionLabel(r){return r.kind==='reference'?`STAGE ${r.collection_id.split('-')[1]} · ${r.condition.replaceAll('-',' ')}`:r.kind==='synthetic'?'SYNTHETIC · ENGINEERING':r.data_class==='mixed_dialogue_exploration'?'LAB · MODEL DIALOGUES':r.data_class.includes('cloud')?'LAB · CLOUD':r.data_class.includes('qualification')?'LAB · QUALIFICATION':'LAB · ENGINEERING';}
function sourceLabel(r){return r.kind==='reference'?'':`<div class="run-source" title="${esc(r.source.path)}">${esc(r.source.path.split('/workspace/').pop())}</div>`;}
function pills(r){return `${topicPills(r)}<span class="pill">${esc(r.condition)}</span>${r.cap_count?`<span class="pill amber">${r.cap_count} capped</span>`:''}${r.repeat_count?'<span class="pill purple">Exact repetition</span>':''}${r.has_thinking?'<span class="pill blue">Recorded reasoning</span>':''}${r.kind==='synthetic'?'<span class="pill amber">Synthetic</span>':''}${!r.complete?'<span class="pill red">Incomplete</span>':''}`;}
function option(value,label,selected){return `<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;}
function renderSidebar(){
 const b=state.boot, f=state.filters;
 $('#sidebar').innerHTML=`<div class="brand"><span class="brand-mark">⌘</span><div><strong>Behavior Lab</strong><small>Observe. Explore. Understand.</small></div></div>
 <div class="side-label">WORKSPACE</div><nav class="nav-links" aria-label="Main navigation">${[['library','library','All transcripts',(b.counts.reference||0)+(b.counts.lab||0)],['topic-atlas','atlas','Topic atlas',''],['finder','filter','Conversation Finder',''],['atlas','atlas','Run atlas',''],['studies','folder','Research collections',''],['workbench','compare','Study workbench',''],['notebook','book','Notebook',''],['topics','tag','Consciousness & self',''],['assessment','compare','Model assessment',''],['purpose','sun','Purpose & musings',''],['results','results','Results','']].map(([v,i,t,c])=>`<button class="side-link ${!state.run&&state.view===v?'active':''}" data-action="view" data-view="${v}">${icon(i)}<span>${t}</span><span class="count">${c}</span></button>`).join('')}</nav>
 <div class="collection-links"><div class="side-label">COLLECTIONS</div>${Object.entries(names).map(([id,title],i)=>`<button class="side-link ${f.collection===id?'active':''}" data-action="collection" data-id="${id}">${icon(i===3?'folder':'dot',14)}<span>${esc(title)}</span><span class="count">${b.collections[id]||0}</span></button>`).join('')}<button class="side-link ${f.scope==='synthetic'?'active':''}" data-action="synthetic">${icon('code',14)}<span>Synthetic fixtures</span><span class="count">${b.counts.synthetic||0}</span></button></div>
 ${(b.studies||[]).map(d=>`<button class="side-study" data-action="study-open" data-id="${d.id}">${icon('folder',12)}<span>${esc(d.title)}</span></button>`).join('')}<div class="side-label">YOUR TAGS</div><div class="side-tags">${Object.entries(b.tags).length?Object.entries(b.tags).map(([tag,count])=>`<button class="tag ${f.tag===tag?'active':''}" data-action="tag-filter" data-tag="${esc(tag)}">${esc(tag)} <span>${count}</span></button>`).join(''):'<span class="small muted">Save a passage to begin.</span>'}</div>
 <div class="side-footer"><span class="live-dot"></span> <strong>Local evidence, close at hand</strong><br>Source transcripts stay unchanged.<br>Notes are saved on this Mac.<br><button class="quiet" data-action="sources">Source index · ${b.issues.length} notice${b.issues.length===1?'':'s'}</button></div>`;
}
function pageTop(title,subtitle){return `<div class="page-heading"><div><div class="eyebrow">THE OBSERVATION WORKSPACE</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="heading-stamp">BEHAVIOR LABORATORY<br>EXPLORER / 01</div></div>`;}
function tabs(){return `<div class="view-tabs" role="navigation" aria-label="Explorer views">${[['library','library','Library'],['atlas','atlas','Run atlas'],['notebook','book','Notebook'],['results','results','Results']].map(([v,i,t])=>`<button class="view-tab ${state.view===v?'active':''}" data-action="view" data-view="${v}">${icon(i,14)} ${t}</button>`).join('')}</div>`;}
function metrics(result){const s=result.stats;return `<div class="metrics">${[[result.total,'Conversations','Current selection','library'],[s.messages,'Recorded messages','Including flagged partial replies','message'],[s.capped_runs,'Runs with an output cap','Recorded termination, not a label','clock'],[s.repeating_runs,'Runs with exact repetition','6 identical participant replies','atlas']].map(([value,label,foot,i])=>`<div class="metric"><span class="metric-icon">${icon(i,18)}</span><div class="metric-label">${label}</div><div class="metric-value">${num(value)}</div><div class="metric-foot">${foot}</div></div>`).join('')}</div>`;}
function filters(){const f=state.filters;return `<div class="tools"><div class="search">${icon('search')}<input id="search" aria-label="Search transcript text" placeholder="Search the conversations. A phrase, a word, a question…" value="${esc(f.q)}" autocomplete="off"></div><select id="sort" aria-label="Sort transcripts">${[['recent','Newest first'],['name','Run name'],['length','Most words'],['matches','Most matching messages']].map(([v,t])=>option(v,t,f.sort)).join('')}</select></div>
 <div class="filter-row"><span class="label">FILTER BY</span><select id="model" aria-label="Filter by model">${option('','All models',f.model)}${state.boot.models.map(m=>option(m,short(m),f.model)).join('')}</select><select id="condition" aria-label="Filter by experimental condition">${option('','All conditions',f.condition)}${state.boot.conditions.map(c=>option(c,c,f.condition)).join('')}</select><select id="signal" aria-label="Filter by recorded signal">${[['','All recorded signals'],['capped','Has output cap'],['repetition','Has exact repetition'],['thinking','Has recorded reasoning'],['unavailable','Has unavailable messages']].map(([v,t])=>option(v,t,f.signal)).join('')}</select>${topicFilter(f.topic)}${f.tag?`<button class="tag" data-action="tag-filter" data-tag="${esc(f.tag)}">${esc(f.tag)} ×</button>`:''}${f.collection?`<button class="tag" data-action="clear-collection">${esc(names[f.collection]||f.collection)} ×</button>`:''}${f.scope==='synthetic'?'<span class="pill amber">Synthetic only</span>':''}<button class="quiet clear" data-action="clear-filters">Reset filters</button></div>`;}
function legend(){return '<div class="legend"><span><i class="dot"></i>Recorded</span><span><i class="dot repeat"></i>Exact repeat</span><span><i class="dot cap"></i>Capped</span><span><i class="dot blocked"></i>Unavailable</span></div>';}
function timeline(r,full=false){const data=full?r.messages.filter(m=>['X','Y'].includes(m.speaker)):r.timeline;return `<div class="timeline" aria-label="Message map">${data.map(m=>`<button class="tick ${esc(m.status)} ${m.repeat?'repeat':''}" style="height:${Math.min(24,Math.max(7,Math.sqrt(m.words??(m.text||'').split(/\s+/).length)*1.6))}px" data-action="open" data-id="${esc(r.id)}" data-message="${esc(m.id)}" title="${esc(m.segment)} · message ${m.turn} · ${esc(m.status)}${m.repeat?' · exact repetition':''}" aria-label="Open ${esc(r.title)}, ${esc(m.segment)}, message ${m.turn}"></button>`).join('')}</div>`;}
function card(r){return `<article class="run-card"><div class="card-inner"><div class="card-top"><span class="eyebrow">${esc(collectionLabel(r))}</span><button class="compare-add ${state.compare.includes(r.id)?'selected':''}" data-action="compare-add" data-id="${r.id}" title="Add to comparison" aria-label="Compare ${esc(r.title)}">${icon(state.compare.includes(r.id)?'check':'compare',15)}</button></div><button class="run-title text-button" data-action="open" data-id="${r.id}">${esc(r.title)} ${icon('arrow',14)}</button><div class="model-label" title="${esc(r.models.join(' / '))}">${modelBadges(r.models)}</div>${setupChips(r)}${sourceLabel(r)}${r.matches.length?`<button class="match-snippet" data-action="open" data-id="${r.id}" data-message="${esc(r.matches[0].id)}"><small>MESSAGE ${r.matches[0].turn} · ${r.match_count} matching message${r.match_count===1?'':'s'}</small><br>${highlight(r.matches[0].text,state.filters.q)}</button>`:`<p class="card-excerpt">${esc(r.preview||'No visible reply recorded.')}</p>`}<div class="card-pills">${pills(r)}</div>${timeline(r)}<div class="timeline-scale"><span>01</span><span>${r.planned_count} UNIQUE NODES</span></div>${r.tags.length?`<div class="inspector-tags">${r.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}</div><footer class="card-footer"><span>${icon('message',11)} ${r.message_count} messages</span><span>${num(r.words)} words</span>${r.note_count?`<span>${icon('book',11)} ${r.note_count}</span>`:''}<span class="push">${stamp(r.date)}</span></footer></article>`;}
function atlas(result){return `<p class="atlas-help">Each row is a run; each mark is a recorded or planned participant message. Height reflects word count. Click any mark to read it in context. Shared prefixes appear once.</p><div class="atlas-panel"><div class="atlas-heading"><span>CONVERSATION</span><span>MESSAGE MAP</span><span>WORDS</span></div>${result.runs.map(r=>`<div class="atlas-row"><div><button class="text-button run-title" data-action="open" data-id="${r.id}">${esc(r.title)}</button><div class="model-label" title="${esc(r.models.join(' / '))}">${modelBadges(r.models)}</div>${sourceLabel(r)}</div>${timeline(r)}<span class="atlas-number">${r.words>=1000?(r.words/1000).toFixed(1)+'k':r.words}</span></div>`).join('')}</div>`;}
function pagination(result){return result.total>40?`<div class="pagination"><button class="button" data-action="page" data-offset="${Math.max(0,state.offset-40)}" ${state.offset===0?'disabled':''}>${icon('back',12)} Previous</button><span>${state.offset+1}–${Math.min(state.offset+40,result.total)} of ${num(result.total)}</span><button class="button" data-action="page" data-offset="${state.offset+40}" ${state.offset+40>=result.total?'disabled':''}>Next ${icon('arrow',12)}</button></div>`:'';}
function resultsView(result){const max=Math.max(1,...Object.values(result.models));return `<div class="result-columns"><section><div class="result-panel"><h2>Coverage of the current selection</h2><p>Counts of conversations by recorded model. Mixed-model roots appear for both participants; these rows are not additive.</p>${Object.entries(result.models).sort((a,b)=>b[1]-a[1]).map(([m,n])=>`<div class="model-row">${modelBadge(m)}<div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><span class="mono">${n}</span></div>`).join('')}</div><div class="result-caution">These are inventory and recorded-behavior counts. They are not estimates of nonduality, consciousness or validated semantic labels. Laboratory branches share roots; historical continuations after caps remain flagged.</div></section><aside><div class="eyebrow" style="margin:2px 0 15px">EXPERIMENT REPORTS</div>${state.boot.reports.map(r=>`<button class="report-link" data-action="report" data-id="${r.id}">${icon('document',17)}<span>${esc(r.title)}</span>${icon('arrow',13)}</button>`).join('')}<p class="source-note">Reports cover their original recorded samples and do not change with the filters above. Drafts and engineering results retain their status.</p></aside></div>`;}
async function loadLibrary(preserveFocus=false){
 const version=++state.request;const pos=preserveFocus?$('#search')?.selectionStart:null;
 const params=new URLSearchParams({...state.filters,offset:state.offset,limit:40});
 history.replaceState(null,'','#'+new URLSearchParams(listRoute()).toString());
 try{const result=await api('/api/runs?'+params);if(version!==state.request||state.run)return;state.result=result;
 const titles={library:['Transcript library','Follow an idea from its first words to its final reply.'],atlas:['A map of the conversations','See the shape of a run, then move closer.'],results:['Results & experimental context','Read the outcomes with their conditions in view.']};
 const [title,sub]=titles[state.view]||titles.library;
 $('#main').innerHTML=`<div class="content">${pageTop(title,sub)}${metrics(result)}${tabs()}${filters()}<div class="results-meta"><span><strong>${num(result.total)} conversations</strong>${state.filters.q?' matching “'+esc(state.filters.q)+'”':state.filters.collection?' in '+esc(names[state.filters.collection]||state.filters.collection):' · '+(state.filters.scope==='synthetic'?'synthetic fixtures':'reference & laboratory evidence')}</span>${legend()}</div>${state.view==='results'?resultsView(result):result.total?(state.view==='atlas'?atlas(result):`<div class="run-grid">${result.runs.map(card).join('')}</div>`)+pagination(result):'<div class="empty"><h2>No conversations match these filters.</h2><p>Try a shorter phrase or reset one of the filters.</p><button class="button" data-action="clear-filters">Reset filters</button></div>'}</div>`;
 renderSidebar();renderCompareTray();if(preserveFocus&&pos!==null){$('#search').focus();$('#search').setSelectionRange(pos,pos);}
 }catch(e){showError(e);}
}
function settingRows(r){
 const format=v=>v===undefined||v===null?'Not recorded':String(v);
 const value=(field,suffix='')=>{
  const one=(settings,speaker)=>{const o=settings.options||settings.decoding||settings;const v=o[field]??settings[field]??(field==='num_predict'?(settings.max_tokens??settings.max_completion_tokens):field==='think'?(settings.enable_thinking??settings.reasoning?.enabled):undefined);if((v===undefined||v===null)&&field==='num_ctx'&&speaker){const c=r.model_identities?.find(m=>m.speaker===speaker)?.recorded_runtime_context;if(c)return format(c)+suffix+' (runtime)';}return v===undefined||v===null?'Not recorded':format(v)+suffix;};
  if(!r.settings_by_speaker)return one(r.settings);
  const x=one(r.settings_by_speaker.X,'X'),y=one(r.settings_by_speaker.Y,'Y');return x===y?x:'X: '+x+' / Y: '+y;
 };
 return [['Temperature',value('temperature')],['Top p / top k',value('top_p')+' / '+value('top_k')],['Requested cap',value('num_predict',' tokens')],['Context',value('num_ctx',' tokens')],['Thinking mode',value('think').replaceAll('false','Off').replaceAll('true','On')],[r.kind==='reference'?'Seed':'Seed policy',r.kind==='reference'?format(r.settings.seed):(r.seed_policy||'Per request · exact input')],...(r.cost_usd!==undefined?[["Recorded cost",r.cost_usd===null?'Unknown':'$'+Number(r.cost_usd).toFixed(6)],["Provider",r.provider||'Not recorded']]:[]),['Run type',r.kind==='reference'?r.model_kind:r.data_class.includes('qualification')?'Qualification':r.kind==='synthetic'?'Synthetic fixture':r.data_class==='mixed_dialogue_exploration'?'Exploratory model dialogue':r.data_class==='cloud_model_assessment'?'Exploratory model screen':r.data_class.includes('cloud_integration')?'Cloud integration check':r.data_class.includes('cloud')?'Cloud comparison':'Local engineering']];
}
function settingsHtml(r){return `<dl class="setting-list">${settingRows(r).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd class="mono">${esc(v)}</dd></div>`).join('')}</dl>`;}
function branchPath(r,leaf){const wanted=new Set();let s=r.segments.find(s=>s.id===leaf);while(s){wanted.add(s.id);s=r.segments.find(x=>x.id===s.parent);}return r.messages.filter(m=>wanted.has(m.segment));}
function branchForMessage(r,id){const message=r.messages.find(m=>m.id===id);return r.leaves.find(leaf=>branchPath(r,leaf).some(m=>m.id===id))||r.leaves[0];}
function branchButtons(r,selected,compare=false){return r.segments.length>1?`<div class="branch-controls"><span class="small muted">Actual path</span>${r.leaves.map(leaf=>`<button class="branch ${leaf===selected?'active':''}" data-action="${compare?'compare-branch':'branch'}" data-id="${r.id}" data-branch="${esc(leaf)}" title="Follow actual ${esc(leaf)} ancestry">${esc(leaf)}</button>`).join('')}</div>`:'';}
function messageStatus(m){if(m.status==='cap')return 'Output cap reached · partial reply retained';if(m.status==='after_cap')return 'Historical continuation after an earlier cap · runtime validity is not established';if(m.status==='invalid')return 'Recorded invalid reply · '+m.reason;if(m.status==='uncommitted')return 'Saved raw output; no committed outcome yet';return '';}
function messageHtml(m,r,q=''){
 const validText=m.text!==null;const saved=r.notes?.filter(n=>n.message_id===m.id)||[];
 if(!validText)return `<div class="missing-message" id="m-${esc(m.id)}"><span class="mono">${String(m.turn).padStart(2,'0')}</span><span>${esc(m.status==='blocked'?'Unavailable after '+m.blocking_node:m.status==='unresolved'?'Request saved; output unknown':m.status==='not_dispatched'?'Not dispatched · '+(m.reason||'no generation requested'):m.status==='invalid'?'Invalid response · '+(m.reason||'no readable text'):m.status==='intervention'?'Recorded event · '+m.kind:'Planned message; not observed')}</span>${m.request||m.raw_response?`<button class="quiet" data-action="inspect" data-id="${r.id}" data-message="${esc(m.id)}">${icon('code',13)} Request & response</button>`:''}</div>`;
 return `<article class="message ${esc(m.status)}" id="m-${esc(m.id)}" data-message-id="${esc(m.id)}" data-run-id="${r.id}"><header class="message-head"><span class="avatar ${m.speaker==='Y'?'y':m.speaker==='X'?'':'observer'}">${esc(m.speaker==='Observer'?'O':m.speaker)}</span><strong>${esc(m.kind==='third'?'External intervention':'Participant '+m.speaker)}</strong>${modelBadge(m.model,true,m.kind==='third'?'interventions':'participants')}<span class="turn">${m.kind==='third'?'AFTER ':''}${String(m.turn).padStart(2,'0')}</span></header>${messageStatus(m)?`<div class="status-note">${esc(messageStatus(m))}</div>`:''}<div class="message-text ${m.text.length>6500?'compact':''}" data-text-id="${esc(m.id)}">${highlight(m.text,q)}</div>${m.text.length>6500?`<button class="quiet small" data-action="expand-message" data-message="${esc(m.id)}">Show the full reply</button>`:''}${messageTopicFlags(m,r)}${m.thinking_recorded?`<details class="reasoning"><summary>Recorded reasoning${m.thinking?' · '+num(m.thinking.split(/\s+/).length)+' words':' · empty field'}</summary><pre>${esc(m.thinking||'(Recorded empty reasoning field)')}</pre></details>`:''}<footer class="message-foot"><button class="quiet" data-action="save-message" data-id="${r.id}" data-message="${esc(m.id)}">${icon('book',12)} ${saved.length?'Saved · '+saved.length:'Save passage'}</button><button class="quiet" data-action="inspect" data-id="${r.id}" data-message="${esc(m.id)}">${icon('code',13)} ${r.kind==='reference'?'Source record':'Exact input'}</button><button class="quiet" data-action="topic-message" data-id="${r.id}" data-message="${esc(m.id)}">${icon('tag',12)} Flag topic</button><span class="metrics-inline">${num(m.text.split(/\s+/).filter(Boolean).length)} words${m.tokens!==null?' · '+num(m.tokens)+' tokens':''}</span></footer></article>`;
}
function transcriptHtml(messages,r,q=''){
 let html='',segment=null;
 for(let i=0;i<messages.length;i++){
  const m=messages[i];if(m.segment!==segment){segment=m.segment;const s=r.segments.find(s=>s.id===segment);html+=`<div class="segment-heading">${esc(segment==='conversation'?'The conversation':segment)}${s&&segment!=='conversation'?' · '+(s.history==='F'?'Full history':s.history==='R'?'Last 3 messages':s.history)+' · '+s.start+'–'+s.stop:''}</div>`;}
  let end=i+1;while(end<messages.length&&m.text?.trim()&&messages[end].text===m.text&&messages[end].segment===m.segment&&messages[end].status===m.status&&['valid','recorded'].includes(m.status))end++;
  if(end-i>=6){html+=`<details class="repeat-group"><summary>${icon('atlas',13)} ${end-i} identical replies · messages ${m.turn}–${messages[end-1].turn}<span>“${esc(m.text.slice(0,130))}”</span>Expand to inspect or save each original message.</summary>${messages.slice(i,end).map(x=>messageHtml(x,r,q)).join('')}</details>`;i=end-1;}
  else html+=messageHtml(m,r,q);
 }
 return html;
}
function inspector(r){return `<aside class="inspector"><section class="inspector-box"><div class="box-title">${icon('document',13)} System prompt <button class="quiet" data-action="raw-settings" title="All recorded settings">${icon('code',13)}</button></div><p class="prompt-text" id="prompt-text">${esc(r.prompt||(r.data_class.includes('cloud')?'No system message configured.':'System prompt not recorded.'))}</p><button class="quiet" data-action="expand-prompt">Expand prompt ${icon('plus',11)}</button>${r.opening?`<details class="source-note"><summary>Opening cue · X only</summary><p>${esc(r.opening)}</p></details>`:''}</section><section class="inspector-box"><div class="box-title">Experimental setting ${icon('filter',13)}</div><div class="source-note" style="margin-bottom:8px">${esc(r.condition)}</div>${settingsHtml(r)}<button class="quiet" data-action="raw-settings">All recorded settings ${icon('arrow',11)}</button></section><section class="inspector-box"><div class="box-title">Your observations <button class="quiet" data-action="save-run" title="Add a note">${icon('plus',13)}</button></div><div class="inspector-tags">${[...new Set((r.notes||[]).flatMap(n=>n.tags))].map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${r.notes?.length?r.notes.map(n=>`<div class="note-mini">${modelBadges(experimentOf(n.run_id)?.models||[])}${n.quote?`<blockquote>${esc(n.quote)}</blockquote>`:''}<p>${esc(n.text)}</p><button class="quiet" data-action="edit-note" data-note="${n.id}">Edit observation</button></div>`).join(''):'<p class="source-note">Select a passage to keep it, or add a note about this run. Tags are personal observations, separate from formal coding.</p><button class="button" data-action="save-run">'+icon('plus',12)+' Add a note</button>'}</section><section class="inspector-box"><div class="box-title">Source & provenance</div><p class="source-note">${esc(r.source.verification)}</p><p class="source-path">${esc(r.source.original_path||r.source.path.split('/workspace/').pop())}</p><div class="source-note">SHA-256</div><div class="source-path">${esc(r.source.sha256)}</div>${r.source.parser?`<p class="source-note">Parser: ${esc(r.source.parser)}</p>`:''}${r.webui_url?`<a class="button" href="${esc(r.webui_url)}" target="_blank" rel="noopener">Open existing WebUI chat ${icon('external',11)}</a>`:'<p class="source-note">No linked WebUI export for this run.</p>'}</section>${r.probes.length?`<section class="inspector-box"><div class="box-title">Disposable probes</div><p class="source-note">${num(r.probes.reduce((n,p)=>n+p.jobs.length,0))} planned probes linked to this root. Separate from the conversation.</p><button class="button" data-action="probes">Inspect saved probe results</button></section>`:''}</aside>`;}
function renderReader(){const r=state.run,messages=branchPath(r,state.branch);
 $('#main').innerHTML=`<div class="reader"><div class="reader-breadcrumb"><button class="quiet" data-action="back">${icon('back',13)} Back to ${state.view==='workbench'?'Study workbench':state.activeStudy?'research collection':state.view==='finder'?'Conversation Finder':state.view==='assessment'?'model assessment':state.view==='topic-atlas'?'topic atlas':state.view==='topics'?'topic flags':state.view==='atlas'?'run atlas':'library'}</button><span>/</span><span>${esc(collectionLabel(r))}</span><span>/</span><span>${esc(r.title)}</span></div><div class="reader-heading"><div><div class="eyebrow">READ THE EVIDENCE</div><h1>${esc(r.title)}</h1><div class="card-pills">${pills(r)}</div></div><div class="actions"><button class="button" data-action="study-add-run">${icon('folder',12)} Add to collection</button><button class="button" data-action="compare-add" data-id="${r.id}">${icon('compare',13)} ${state.compare.includes(r.id)?'In comparison':'Compare'}</button><button class="button primary" data-action="save-run">${icon('plus',13)} Add observation</button></div></div>${readerSetup(r)}<div class="reader-columns"><section class="transcript-panel"><div class="run-map"><div class="map-top"><span>${messages.filter(m=>m.text!==null&&['X','Y'].includes(m.speaker)).length} visible participant replies · ${messages.filter(m=>['X','Y'].includes(m.speaker)).length} ${r.kind==='reference'?'recorded':'planned'} positions on this path</span>${icon('atlas',13)}</div>${timeline({...r,messages},true)}${branchButtons(r,state.branch)}${r.segments.length>1?'<p class="source-note" style="margin:8px 0 0">F: full history · R: latest 3 messages. Restored paths follow their actual ancestors.</p>':''}<div class="timeline-scale"><span>BEGINNING</span><span>ACTUAL ANCESTRY</span><span>END</span></div></div><div class="reader-tools"><div class="search">${icon('search',14)}<input id="run-search" aria-label="Find in this transcript" placeholder="Find a word or phrase in this transcript…" value="${esc(state.runQuery)}"></div><span class="small muted" id="run-match-count">${state.runQuery?messages.filter(m=>(m.text||'').toLowerCase().includes(state.runQuery.toLowerCase())).length+' matching replies':'Select text to save a passage'}</span></div><div id="transcript">${transcriptHtml(messages,r,state.runQuery)}</div><div class="reader-nav"><button class="button" data-action="previous-run">${icon('back',12)} Previous run</button><button class="button" data-action="next-run">Next run ${icon('arrow',12)}</button></div></section>${inspector(r)}</div></div>`;
 renderSidebar();renderCompareTray();
}
function focusMessage(id){if(!id)return;const el=document.getElementById('m-'+id);if(!el)return;const group=el.closest('.repeat-group');if(group)group.open=true;el.classList.add('focused');el.scrollIntoView({block:'center',behavior:'auto'});}
async function loadReader(id,branch,target){const version=++routeVersion;try{const r=await api('/api/runs/'+encodeURIComponent(id));if(version!==routeVersion)return;state.run=r;state.notes=r.notes;state.branch=r.leaves.includes(branch)?branch:branchForMessage(r,target);state.runQuery=state.activeStudy?'':state.view==='finder'?(state.finderFilters?.q||''):state.filters.q;renderReader();requestAnimationFrame(()=>focusMessage(target));}catch(e){showError(e);}}
function renderCompareTray(){const el=$('#compare-tray');if(!state.compare.length||new URLSearchParams(location.hash.slice(1)).has('compare')){el.innerHTML='';return;}const title=id=>state.compareLabels[id]||state.result?.runs.find(r=>r.id===id)?.title||(state.run?.id===id?state.run.title:'Selected run');el.innerHTML=`<div class="compare-tray-inner"><span>${icon('compare',16)} Compare conversations</span>${state.compare.map(id=>`<span class="compare-chip">${esc(title(id))}</span>`).join('')}<button class="button" data-action="compare-open" ${state.compare.length<2?'disabled':''}>Open side by side ${icon('arrow',12)}</button><button class="quiet" data-action="compare-clear" aria-label="Clear comparison">${icon('close',14)}</button></div>`;}
async function loadCompare(ids){state.compare=[...new Set(ids)];const version=++routeVersion;const runs=await Promise.all(ids.map(id=>api('/api/runs/'+encodeURIComponent(id))));if(version!==routeVersion)return;state.compareRuns=runs;for(const r of runs)state.compareLabels[r.id]=r.title;state.run=null;renderSidebar();$('#main').innerHTML=`<div class="compare-page"><div class="compare-heading"><div><button class="quiet" data-action="back">${icon('back',13)} Back to ${state.view==='finder'?'Conversation Finder':'library'}</button><h1>Read side by side</h1><p class="small muted">Two runs, their actual settings, and their independent histories.</p></div><button class="button" data-action="compare-clear">Close comparison</button></div><div class="compare-columns">${runs.map(r=>`<section class="compare-column" data-compare-run="${r.id}"><header><div class="eyebrow">${esc(collectionLabel(r))}</div><h2>${esc(r.title)}</h2><div class="model-label">${modelBadges(r.models)}</div><div class="card-pills" style="margin-top:12px">${settingRows(r).filter((_,i)=>[0,2,3].includes(i)).map(([k,v])=>`<span class="pill">${esc(k)}: ${esc(v)}</span>`).join('')}</div><details style="margin-top:15px"><summary>Prompt & experimental settings</summary><p class="prompt-text">${esc(r.prompt)}</p>${settingsHtml(r)}</details>${branchButtons(r,r.leaves[0],true)}</header><div class="compare-transcript">${transcriptHtml(branchPath(r,r.leaves[0]),r,state.filters.q)}</div></section>`).join('')}</div></div>`;renderCompareTray();}
function noteCard(n){return `<article class="notebook-card"><div class="card-top"><span class="eyebrow">${n.quote?'SAVED PASSAGE':'RUN OBSERVATION'}</span><span class="small muted">${stamp(n.updated_at)}</span></div><button class="text-button run-title" data-action="open" data-id="${esc(n.run_id)}" data-message="${esc(n.message_id||'')}">${esc(n.run_title)} ${icon('arrow',13)}</button>${modelBadges(experimentOf(n.run_id)?.models||[])}${n.quote?`<blockquote>${esc(n.quote)}</blockquote>`:''}${n.text?`<p class="note-text">${esc(n.text)}</p>`:''}<div class="notebook-tags">${n.tags.map(t=>`<button class="tag" data-action="notebook-tag" data-tag="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="notebook-meta"><span>Personal observation · ${esc(n.author)}${n.study_id?' · in research collection':''}</span><button class="quiet" data-action="edit-note" data-note="${n.id}">Edit ${icon('code',11)}</button></div></article>`;}
async function loadNotebook(){const version=++state.request;const data=await api('/api/notes');if(version!==state.request||state.run)return;state.notes=data.notes;renderNotebook();}
function renderNotebook(preserve=false){const pos=preserve?$('#note-search')?.selectionStart:null;const q=state.noteQuery.toLowerCase(),notes=state.notes.filter(n=>!q||[n.quote,n.text,n.run_title,...n.tags].join(' ').toLowerCase().includes(q));$('#main').innerHTML=`<div class="content">${pageTop('Your field notebook','Keep the passages that matter, and the questions they leave you with.')}${tabs()}<div class="notebook-toolbar"><div class="search">${icon('search')}<input id="note-search" aria-label="Search notebook" placeholder="Find a passage, note, or tag…" value="${esc(state.noteQuery)}"></div><a class="button" href="/api/notes/export" download>${icon('download',14)} Export notebook</a></div><p class="notebook-explainer">${num(notes.length)} saved observations. Exact quotes link to their source messages. These notes are separate from formal research annotations.</p>${notes.length?`<div class="notebook-grid">${notes.map(noteCard).join('')}</div>`:'<div class="empty">'+icon('book',30)+'<h2>Good questions begin with a passage.</h2><p>Open a transcript, select some text, and save it here with your own tags and observations.</p><button class="button" data-action="view" data-view="library">Explore the library '+icon('arrow',12)+'</button></div>'}</div>`;renderSidebar();if(preserve&&pos!==null){$('#note-search').focus();$('#note-search').setSelectionRange(pos,pos);}}
function dialog(title,body,footer='',wide=false){const d=$('#dialog');d.classList.toggle('dialog-wide',wide);$('#dialog-content').innerHTML=`<header class="dialog-header"><h2>${esc(title)}</h2><button class="quiet" data-action="close-dialog" aria-label="Close dialog">${icon('close',17)}</button></header><div class="dialog-body">${body}<div class="dialog-error" id="dialog-error" role="alert"></div></div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}`;if(!d.open)d.showModal();}
function openNote(note){state.editing=note;dialog(note.id?'Edit observation':note.quote?'Keep this passage':'Add an observation',`<div class="eyebrow">${esc(note.run_title||state.run?.title||'Source-linked note')}</div>${note.quote?`<blockquote>${esc(note.quote)}</blockquote>`:''}<label for="note-text">What do you notice?</label><textarea id="note-text" rows="5" placeholder="An observation, a connection, a question to return to…">${esc(note.text||'')}</textarea><label for="note-tags">Tags · separated by commas</label><input id="note-tags" placeholder="e.g. understanding, change of topic, follow up" value="${esc((note.tags||[]).join(', '))}">${noteStudyField(note)}<p class="source-note">Saved locally in your research notebook. The original transcript and formal annotations stay unchanged.</p>`,`${note.id?'<button class="quiet" data-action="remove-note">Remove from notebook</button>':''}<button class="button" data-action="close-dialog">Cancel</button><button class="button primary" id="save-note" data-action="save-note">${icon('book',13)} Save observation</button>`);setTimeout(()=>$('#note-text').focus(),0);}
function findRun(id){return state.run?.id===id?state.run:state.compareRuns?.find(r=>r.id===id);}
function saveMessage(id,message){const r=findRun(id),m=r.messages.find(m=>m.id===message);if(!m.text?.length){toast('This message has no text to save.');return;}openNote({run_id:r.id,run_title:r.title,message_id:m.id,quote:m.text,start:0,end:[...m.text].length,tags:[],text:''});}
async function afterNoteChange(){const boot=await api('/api/bootstrap');state.boot=boot;$('#dialog').close();if(state.run){state.run=await api('/api/runs/'+state.run.id);state.notes=state.run.notes;const y=scrollY;renderReader();scrollTo(0,y);}else if(state.compareRuns&&new URLSearchParams(location.hash.slice(1)).has('compare'))await loadCompare(state.compare);else if(state.view==='notebook')await loadNotebook();else if(state.view==='studies')await loadStudies(state.activeStudy);else await loadLibrary();renderSidebar();}
function reportMarkdown(markdown){
 const inline=t=>esc(t).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1');
 const lines=markdown.split('\n');let html='',code=false,block=[],table=[];const flushTable=()=>{if(!table.length)return;html+='<table>'+table.filter(x=>!/^\|[\s:|\-]+\|$/.test(x)).map((x,i)=>'<tr>'+x.split('|').slice(1,-1).map(c=>`<${i===0?'th':'td'}>${inline(c.trim())}</${i===0?'th':'td'}>`).join('')+'</tr>').join('')+'</table>';table=[];};
 for(const line of lines){if(line.startsWith('```')){flushTable();if(code){html+='<pre>'+esc(block.join('\n'))+'</pre>';block=[];}code=!code;continue;}if(code){block.push(line);continue;}if(line.startsWith('|')){table.push(line);continue;}flushTable();if(/^#{1,3} /.test(line)){const n=Math.min(3,line.match(/^#+/)[0].length+1);html+=`<h${n}>${inline(line.replace(/^#+ /,''))}</h${n}>`;}else if(line.trim())html+='<p>'+inline(line)+'</p>';}
 flushTable();return html;
}
function showError(e){toast(e.message||String(e));if(!state.result&&!state.run)$('#main').innerHTML=`<div class="content"><div class="error-banner">${esc(e.message)}<p><button class="button" data-action="retry">Try again</button></p></div></div>`;}
async function route(){
 state.request++;routeVersion++;state.selection=null;$('.selection-bar')?.remove();const p=new URLSearchParams(location.hash.slice(1));
 state.activeStudy=p.get('fromStudy')||p.get('study')||null;state.returnFinding=p.get('fromFinding')||p.get('finding')||null;
 if(p.has('fromFinder')){try{state.view='finder';state.finderFilters=JSON.parse(p.get('fromFinder'));state.finderResult={offset:Number(p.get('finderOffset'))||0};}catch(e){showError(e);return;}}
 if(p.get('view')==='finder'){try{await loadFinder(JSON.parse(p.get('finder')||'{}'),Number(p.get('offset'))||0);}catch(e){showError(e);}return;}
 if(p.has('fromWorkbench')){state.view='workbench';state.benchCohort=p.get('fromWorkbench');state.benchPicks=(p.get('picks')||'').split(',').filter(Boolean);state.activeStudy=state.benchCohort;}
 if(p.get('view')==='workbench'){try{await loadWorkbench(p.get('cohort'),p.get('picks'));}catch(e){showError(e);}return;}
 if(p.has('study')){try{await loadStudies(p.get('study'));}catch(e){showError(e);}return;}
 if(p.get('view')==='purpose'){try{await loadMusings(p.get('section'),p.get('musing'));}catch(e){showError(e);}return;}
 if(p.get('view')==='studies'){await loadStudies();return;}
 if(p.get('view')==='assessment'){await loadAssessments();return;}
 if(p.get('view')==='topic-atlas'){await loadTopicAtlas(atlasRouteFilters(p));return;}
 if(p.has('fromAtlas')){state.view='topic-atlas';state.atlasFilters=atlasRouteFilters(p);}
 if(p.get('view')==='topics'){await loadTopics(p.get('topic')||'any');return;}
 if(p.has('fromAssessment'))state.view='assessment';
 if(p.has('run')){await loadReader(p.get('run'),p.get('branch'),p.get('message'));return;}
 state.run=null;routeVersion++;if(p.has('compare')){try{await loadCompare(p.get('compare').split(',').slice(0,2));}catch(e){showError(e);}return;}
 state.view=['library','atlas','results','notebook'].includes(p.get('view'))?p.get('view'):'library';
 if(state.view!=='notebook'){for(const key of Object.keys(state.filters))state.filters[key]=p.get(key)||(key==='scope'?'all':key==='sort'?'recent':'');state.offset=Math.max(0,Number(p.get('offset'))||0);}
 renderSidebar();renderCompareTray();
 if(state.view==='notebook')await loadNotebook();else await loadLibrary();
}

document.addEventListener('click',async event=>{
 if(event.target.closest('.skip-link')){event.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
 try{
 if(a==='view'){state.run=null;state.offset=0;state.view=el.dataset.view;if(state.view==='library'){state.filters.scope='all';state.filters.collection='';}if(state.view==='finder')finderGo();else library(state.view);}
 else if(a==='collection'){state.filters={...state.filters,collection:el.dataset.id,scope:el.dataset.id==='lab'?'lab':'reference'};state.offset=0;state.run=null;if(['notebook','studies','assessment','topics','topic-atlas','finder','purpose','workbench'].includes(state.view))state.view='library';library();}
 else if(a==='synthetic'){state.filters={...state.filters,scope:'synthetic',collection:'',model:'',condition:''};state.offset=0;state.run=null;state.view='library';library();}
 else if(a==='open'){if($('#dialog').open)$('#dialog').close();if(el.dataset.study)state.activeStudy=el.dataset.study;if(el.dataset.finding)state.returnFinding=el.dataset.finding;go({run:el.dataset.id,...(el.dataset.message?{message:el.dataset.message}:{})});}
 else if(a==='back'){state.run=null;if(state.view==='workbench')benchGo();else if(state.activeStudy)go({study:state.activeStudy,...(state.returnFinding?{finding:state.returnFinding}:{})});else if(state.view==='finder')finderGo({},state.finderResult?.offset||0);else if(state.view==='topic-atlas')atlasGo();else library();}
 else if(a==='clear-filters'){state.filters={scope:'all',collection:'',q:'',model:'',condition:'',signal:'',topic:'',tag:'',sort:'recent'};state.offset=0;await loadLibrary();}
 else if(a==='clear-collection'){state.filters.collection='';state.filters.scope='all';state.offset=0;await loadLibrary();}
 else if(a==='tag-filter'){state.filters.tag=state.filters.tag===el.dataset.tag?'':el.dataset.tag;state.run=null;state.view='library';state.offset=0;library();}
 else if(a==='notebook-tag'){state.noteQuery=el.dataset.tag;renderNotebook();}
 else if(a==='model-filter'){state.filters.model=el.dataset.model;state.offset=0;state.view='library';library();}
 else if(a==='page'){state.offset=Number(el.dataset.offset);await loadLibrary();scrollTo({top:200,behavior:'smooth'});}
 else if(a==='branch')go({run:state.run.id,branch:el.dataset.branch});
 else if(a==='compare-branch'){const r=findRun(el.dataset.id),section=el.closest('.compare-column');section.querySelectorAll('.branch').forEach(b=>b.classList.toggle('active',b===el));$('.compare-transcript',section).innerHTML=transcriptHtml(branchPath(r,el.dataset.branch),r,state.filters.q);}
 else if(a==='compare-add'){const id=el.dataset.id;state.compareLabels[id]=el.dataset.title||(state.run?.id===id?state.run.title:state.result?.runs.find(r=>r.id===id)?.title)||'Selected run';if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<2)state.compare.push(id);else{toast('Choose two runs. Clear one to select another.');return;}el.classList.toggle('selected',state.compare.includes(id));renderCompareTray();if(state.compare.length===1)toast('One run selected. Choose another from the library.');}
 else if(a==='compare-open')go({compare:state.compare.join(',')});
 else if(a==='compare-clear'){state.compare=[];state.compareRuns=null;renderCompareTray();if(new URLSearchParams(location.hash.slice(1)).has('compare')){if(state.view==='finder')finderGo({},state.finderResult?.offset||0);else library();}else if(!state.run){if(state.view==='assessment')await loadAssessments();else if(state.view==='finder')await loadFinder(state.finderFilters,state.finderResult?.offset||0);else await loadLibrary();}}
 else if(a==='expand-prompt'){$('#prompt-text').classList.toggle('expanded');el.textContent=$('#prompt-text').classList.contains('expanded')?'Show less':'Expand prompt';}
 else if(a==='expand-message'){const body=document.getElementById('m-'+el.dataset.message).querySelector('.message-text');body.classList.toggle('compact');el.textContent=body.classList.contains('compact')?'Show the full reply':'Collapse long reply';}
 else if(a==='save-run')openNote({run_id:state.run.id,run_title:state.run.title,message_id:null,quote:null,start:null,end:null,text:'',tags:[]});
 else if(a==='save-message')saveMessage(el.dataset.id,el.dataset.message);
 else if(a==='save-selection'){openNote({...state.selection,text:'',tags:[]});$('.selection-bar')?.remove();window.getSelection()?.removeAllRanges();}
 else if(a==='edit-note'){const n=state.notes.find(n=>n.id===el.dataset.note);if(n)openNote(n);}
 else if(a==='save-note'){el.disabled=true;try{const study_id=$('#note-study').value||null;if(study_id)await ensureStudyMember(study_id,state.editing.run_id);await api('/api/notes',{...state.editing,study_id,text:$('#note-text').value,tags:$('#note-tags').value.split(',').map(t=>t.trim()).filter(Boolean)});await afterNoteChange();toast('Observation saved to your notebook.');}catch(e){$('#dialog-error').textContent=e.message;el.disabled=false;}}
 else if(a==='remove-note'){await api('/api/notes/remove',{id:state.editing.id,revision:state.editing.revision});await afterNoteChange();toast('Removed from notebook. Revision history retained.');}
 else if(a==='close-dialog')$('#dialog').close();
 else if(a==='raw-settings')dialog('Recorded experimental settings',`<p class="source-note">These are source values. A missing field is not inferred from a current model default.</p><pre class="raw">${esc(JSON.stringify({prompt:state.run.prompt,opening:state.run.opening,settings:state.run.settings,settings_by_speaker:state.run.settings_by_speaker,model_identities:state.run.model_identities,source:state.run.source},null,2))}</pre>`,'',true);
 else if(a==='inspect'){const r=findRun(el.dataset.id),m=r.messages.find(m=>m.id===el.dataset.message);dialog(r.kind==='reference'?'Original source record':r.data_class.includes('cloud')?'Saved API request':'Exact input seen by the participant',`<p class="source-note">${r.kind==='reference'?'Historical request payloads were not recorded. This is the preserved original message record.':r.data_class.includes('cloud')?'This is the exact submitted API request. Provider-side transformations and hidden templates are not captured.':'The saved request contains the actual role mapping and history delivered for this message.'}</p><pre class="raw">${esc(JSON.stringify(m.request||m.raw_record||{status:m.status,reason:m.reason},null,2))}</pre>${m.raw_response?`<details><summary>Saved raw response</summary><pre class="raw">${esc(m.raw_response)}</pre></details>`:''}`,'',true);}
 else if(a==='probes')dialog('Saved disposable probe results',`<p class="source-note">These checks never enter the main conversation. Scores retain their frozen parser and uncertainty.</p><pre class="raw">${esc(JSON.stringify(state.run.probes,null,2))}</pre>`,'',true);
 else if(a==='sources')dialog('Local source index',`<p class="source-note">Indexed ${esc(state.boot.indexed_at)}. ${num(state.boot.counts.reference)} reference runs, ${num(state.boot.counts.lab)} laboratory roots and ${num(state.boot.counts.synthetic)} synthetic roots. Private files and software copies are not scanned.</p>${state.boot.issues.length?`<ul class="issue-list">${state.boot.issues.map(i=>`<li><span class="mono">${esc(i.source.split('/workspace/').pop())}</span><br>${esc(i.reason)}</li>`).join('')}</ul>`:'<p>All discoverable conversation sources opened successfully.</p>'}`);
 else if(a==='report'){const r=await api('/api/reports/'+el.dataset.id);dialog(r.title,`<div class="report-text">${reportMarkdown(r.markdown)}</div>`,'',true);}
 else if(a==='previous-run'||a==='next-run'){const list=state.result?.runs||[],index=list.findIndex(r=>r.id===state.run.id),next=list[index+(a==='next-run'?1:-1)];if(next)go({run:next.id});else toast('At the edge of this page. Return to the library to browse more.');}
 else if(a==='retry')await route();
 }catch(e){toast(e.message);}
});
document.addEventListener('input',event=>{
 const el=event.target;if(el.id==='search'){state.filters.q=el.value;state.offset=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadLibrary(true),200);}
 else if(el.id==='note-search'){state.noteQuery=el.value;renderNotebook(true);}
 else if(el.id==='run-search'){state.runQuery=el.value;const messages=branchPath(state.run,state.branch);$('#transcript').innerHTML=transcriptHtml(messages,state.run,el.value);$('#run-match-count').textContent=el.value?messages.filter(m=>(m.text||'').toLowerCase().includes(el.value.toLowerCase())).length+' matching replies':'Select text to save a passage';if(el.value)$('#transcript').querySelectorAll('.repeat-group').forEach(d=>{if($('mark',d))d.open=true;});}
});
document.addEventListener('change',event=>{if(['model','condition','signal','topic','sort'].includes(event.target.id)){state.filters[event.target.id]=event.target.value;state.offset=0;loadLibrary();}});
document.addEventListener('mouseup',event=>{
 if(event.target.closest('dialog,.selection-bar'))return;
 const selection=window.getSelection();if(!selection||selection.isCollapsed){$('.selection-bar')?.remove();return;}
 const range=selection.getRangeAt(0),startEl=range.startContainer.nodeType===1?range.startContainer:range.startContainer.parentElement,endEl=range.endContainer.nodeType===1?range.endContainer:range.endContainer.parentElement;
 const body=startEl.closest('.message-text');if(!body||endEl.closest('.message-text')!==body)return;
 const article=body.closest('.message'),r=findRun(article.dataset.runId);if(!r)return;
 const before=range.cloneRange();before.selectNodeContents(body);before.setEnd(range.startContainer,range.startOffset);
 const start=[...before.toString()].length,quote=range.toString();if(!quote.trim())return;
 state.selection={run_id:r.id,run_title:r.title,message_id:article.dataset.messageId,quote,start,end:start+[...quote].length};
 $('.selection-bar')?.remove();const b=document.createElement('div');b.className='selection-bar';b.innerHTML='<button class="quiet" data-action="save-selection">'+icon('book',13)+' Save passage</button><button class="quiet" data-action="topic-selection">'+icon('tag',13)+' Flag topic</button>';document.body.append(b);
});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#dialog').open){const search=$('#run-search')||$('#search')||$('#note-search');if(search){e.preventDefault();search.focus();}}if(e.key==='Escape')$('.selection-bar')?.remove();});
$('#refresh').addEventListener('click',async()=>{const b=$('#refresh');b.disabled=true;try{await api('/api/refresh',{});state.boot=await api('/api/bootstrap');await route();toast('Local evidence refreshed.');}catch(e){toast(e.message);}finally{b.disabled=false;}});
window.addEventListener('hashchange',()=>{scrollTo(0,0);route();});
(async()=>{try{state.boot=await api('/api/bootstrap');await route();}catch(e){showError(e);}})();
